        return paymentMethodRepository.saveAndFlush(UserPaymentMethod.builder()
                .user(owner)
                .stripePaymentMethodId(token)
                .brand("visa")
                .last4("4242")
                .expMonth(12)
                .expYear(2030)
                .deleted(deleted)
                .build());
    }

